public class JITOptimizationDemo {
    private static final int ITERATIONS = 100_000_000;

    public static void main(String[] args) {
        long start = System.currentTimeMillis();
        long sum = 0;

        // The loop back-edge counter will trigger C1/C2 compilation
        for (int i = 0; i < ITERATIONS; i++) {
            sum += compute(i);
        }

        long end = System.currentTimeMillis();
        System.out.println("Execution Time: " + (end - start) + "ms, Sum: " + sum);
    }

    private static int compute(int x) {
        // Small method, prime candidate for JIT method inlining
        return x * 2;
    }
}
